//! `docs/reference/mcp-core-tools.md` (WP-2I.01): the core MCP tools, generated by
//! `cargo xtask gen` from the core tool table (`crates/cutweave-api/mcp_core.toml`) and the
//! registry of the full engine (the core engine's, plus `render.frame`).

use std::fmt::Write as _;
use std::sync::Arc;

use cutweave_api::mcp::core::{CoreTable, MAX_DESCRIPTION_CHARS, META_ALWAYS_LOAD};
use cutweave_api::mcp::instructions::MAX_INSTRUCTIONS_CHARS;
use cutweave_api::mcp::{Catalog, Profile, catalog};
use cutweave_commands::Registry;

/// The generated file, workspace-relative.
pub const REFERENCE: &str = "docs/reference/mcp-core-tools.md";

fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}

fn hints(meta: &cutweave_commands::CommandMeta) -> String {
    let a = meta.annotations;
    let mut out = Vec::new();
    if a.read_only {
        out.push("read-only");
    }
    if a.destructive {
        out.push("destructive");
    }
    if a.idempotent {
        out.push("idempotent");
    }
    if a.open_world {
        out.push("open-world");
    }
    if out.is_empty() {
        "-".to_owned()
    } else {
        out.join(", ")
    }
}

/// The registry the full engine lists its tools from: `registry` plus `render.frame`, which
/// only an engine with a renderer registers.
fn full_registry(mut registry: Registry) -> Result<Registry, String> {
    registry
        .register::<cutweave_render::query::RenderFrame>()
        .map_err(|e| e.to_string())?;
    Ok(registry)
}

/// The page's opening: what is listed, the sizes against the budgets, and the rules.
fn overview(out: &mut String, registry: &Arc<Registry>, table: &CoreTable) {
    out.push_str(
        "The tools an agent sees in `tools/list` on `/mcp` (the standard profile; arch §14). \
         Generated from the core tool table, `crates/cutweave-api/mcp_core.toml`, and the \
         command registry.\n\n",
    );
    let standard = Catalog::new(Arc::clone(registry), Profile::Standard);
    let size = standard.size();
    let _ = writeln!(
        out,
        "- **Listed:** {} tools ({} core and the {} generic ones), {} bytes, about {} tokens \
         (`ceil(bytes / 4)`). The budget is {} tools and {} tokens.",
        size.tools,
        table.tools.len(),
        catalog::GENERIC_TOOLS.len(),
        size.bytes,
        size.tokens(),
        table.budget.max_tools,
        table.budget.max_tokens
    );
    for profile in [Profile::Minimal, Profile::Full, Profile::Described] {
        let size = Catalog::new(Arc::clone(registry), profile).size();
        let budget = profile.budget();
        let _ = writeln!(
            out,
            "- **`/mcp{}`** ({}): {} tools, about {} tokens of {}.",
            profile.route(),
            profile.name(),
            size.tools,
            size.tokens(),
            budget.max_tokens
        );
    }
    let _ = writeln!(
        out,
        "- **Server instructions:** {} characters of at most {MAX_INSTRUCTIONS_CHARS}: a map \
         of the command namespaces, how to find, describe and run a command, batches, the \
         revision and undo. Built from the registry and the `[[namespace]]` lines of the core \
         tool table.",
        standard.instructions().chars().count()
    );
    let _ = writeln!(
        out,
        "- **Loaded at the start:** {} carry `_meta` `\"{META_ALWAYS_LOAD}\": true`, which \
         asks a client that defers tool definitions (Claude Code's tool search) to load them \
         at the start. They are what an agent needs before it can search; other clients \
         ignore the key. Marked **always** below.",
        table
            .always_loaded()
            .iter()
            .map(|name| format!("`{name}`"))
            .collect::<Vec<_>>()
            .join(", ")
    );
    out.push_str(
        "- **Names:** a tool is named after its command with `.` replaced by `_` \
         (`clip.split` is `clip_split`). A core tool is only that command: the same input \
         schema, result and errors as over JSON-RPC and the CLI.\n",
    );
    let _ = writeln!(
        out,
        "- **Descriptions:** the text below followed by `E.g.` and the example, at most {MAX_DESCRIPTION_CHARS} \
         characters. In an example `…` stands for the 32 hex digits of an id.\n\
         - **Parameters:** a listed input schema validates exactly like the command's. On \
         `/mcp` it carries no parameter descriptions (they do not fit the budget); \
         `cutweave_describe_command` returns them, with the output schema. \
         `/mcp/described` lists the same tools in the same order with every parameter \
         description, for clients that defer tool definitions and load one when the model \
         asks for it (ADR-0040); the two lists accept the same values.\n\
         - **Results:** the command's output as `structuredContent`; the document revision \
         after the call is in the result's `_meta` (`io.cutweave/rev`) and in its first text \
         line. An error is a result with `isError`, a `code`, a `message`, the `path` of the \
         argument when known and a `hint` on what to do next.\n"
    );
}

/// The reference page.
///
/// # Errors
/// A table entry without a registered command, or a registry that refuses `render.frame`.
pub fn reference_markdown(registry: Registry) -> Result<String, String> {
    let registry = Arc::new(full_registry(registry)?);
    let table = CoreTable::get();
    let mut out = String::new();
    out.push_str("<!-- @generated by cargo xtask gen; do not edit -->\n\n");
    out.push_str("# MCP core tools\n\n");
    overview(&mut out, &registry, table);

    out.push_str("## Core tools\n\n");
    out.push_str("| Tool | Command | Hints | Description | Example |\n|---|---|---|---|---|\n");
    for tool in &table.tools {
        let entry = registry
            .get(&tool.command)
            .ok_or_else(|| format!("mcp_core.toml: `{}` is not registered", tool.command))?;
        let _ = writeln!(
            out,
            "| `{}` | `{}` | {} | {} | `{}` |",
            tool.name,
            tool.command,
            if tool.always_load {
                format!("{}, **always**", hints(&entry.meta))
            } else {
                hints(&entry.meta)
            },
            cell(&tool.description),
            cell(&tool.example)
        );
    }

    out.push_str(
        "\n## Generic tools\n\nThey reach every command and query that is not hidden, \
         listed or not.\n\n| Tool | Does |\n|---|---|\n\
         | `cutweave_search_commands` (**always**) | Finds commands and queries by keyword or by the words a user would say (the `[keywords]` of the core tool table) and says how to call each. `detail`: `summary` (default), `names` (names only) or `schema` (adds each hit's input schema, 5 hits at most) |\n\
         | `cutweave_describe_command` (**always**) | Returns one command's docs, annotations and full input and output schemas (`name`), or those of up to 8 commands in one call (`names`) |\n\
         | `cutweave_execute` (**always**) | Runs one or more commands as one all-or-nothing transaction and one undo step |\n\
         | `cutweave_query` | Runs a read-only query by name |\n",
    );

    out.push_str(
        "\n## Not listed yet\n\nPlanned core tools. Until they are listed, a command that \
         exists is reached through the generic tools.\n\n| Tool | Arrives with |\n|---|---|\n",
    );
    for pending in &table.pending {
        let _ = writeln!(out, "| `{}` | {} |", pending.name, pending.arrives);
    }
    Ok(out)
}
